package com.keyforge.nativeload;
import com.fasterxml.jackson.databind.*;import java.time.Instant;import java.util.*;
final class NativeWorkflowParser {private final ObjectMapper m=new ObjectMapper();List<NativeWorkflowRecord> parse(String body){try{JsonNode root=m.readTree(body);if(root==null||!root.isObject()||!root.path("rows").isArray()||root.has("error"))throw new NativeImportException("Unexpected native Workflow response: "+snippet(body));List<NativeWorkflowRecord>out=new ArrayList<>();for(JsonNode n:root.path("rows")){NativeWorkflowRecord r=new NativeWorkflowRecord();r.sourceId=text(n,"sourceId");r.name=text(n,"name");r.type=text(n,"type");r.handler=text(n,"handler");r.description=text(n,"description");r.taskType=text(n,"taskType");r.definition=n.path("definition").toString();r.sourceSystem=text(n,"srcSystem");r.runId=text(n,"extractionRunId");r.created=date(n,"created");r.modified=date(n,"modified");Map<String,Object>business=new TreeMap<>();business.put("sourceId",r.sourceId);business.put("name",r.name);business.put("type",r.type);business.put("handler",r.handler);business.put("description",r.description);business.put("taskType",r.taskType);business.put("definition",r.definition);r.hash=NativeRecordHash.of(business);out.add(r);}return out;}catch(NativeImportException e){throw e;}catch(Exception e){throw new NativeImportException("Failed parsing native Workflow JSON: "+e.getMessage(),e);}}private static String text(JsonNode n,String f){return n.path(f).isMissingNode()||n.path(f).isNull()?null:n.path(f).asText();}private static Instant date(JsonNode n,String f){String s=text(n,f);try{return s==null?null:Instant.parse(s);}catch(Exception e){return null;}}private static String snippet(String s){return s==null?"<null>":s.substring(0,Math.min(350,s.length()));}}
